const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Gobi Desert region (approximate polygon)
  var gobi = ee.Geometry.Polygon([
    [[90, 40], [110, 40], [110, 45], [90, 45], [90, 40]]
  ]);

  // Define date ranges for February 2019 and 2020
  var feb2019 = ee.DateRange('2019-02-01', '2019-02-28');
  var feb2020 = ee.DateRange('2020-02-01', '2020-02-29');

  // Get MODIS AOD data
  var modisAOD = ee.ImageCollection('MODIS/061/MOD04_L2')
    .select('Optical_Depth_055');

  // Filter collections for both periods
  var aod2019 = modisAOD.filterDate(feb2019).filterBounds(gobi);
  var aod2020 = modisAOD.filterDate(feb2020).filterBounds(gobi);

  // Check collection sizes
  var count2019 = aod2019.size().getInfo();
  var count2020 = aod2020.size().getInfo();

  print(`2019 Images: ${count2019}`);
  print(`2020 Images: ${count2020}`);

  if (count2019 === 0 || count2020 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Calculate mean AOD for each period
  var meanAOD2019 = aod2019.mean();
  var meanAOD2020 = aod2020.mean();

  // Reduce regions to get mean values
  var stats2019 = meanAOD2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: gobi,
    scale: 1000,
    maxPixels: 1e9
  });

  var stats2020 = meanAOD2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: gobi,
    scale: 1000,
    maxPixels: 1e9
  });

  var mean2019 = stats2019.get('Optical_Depth_055').getInfo();
  var count2019px = stats2019.get('Optical_Depth_055_count').getInfo();
  var mean2020 = stats2020.get('Optical_Depth_055').getInfo();
  var count2020px = stats2020.get('Optical_Depth_055_count').getInfo();

  print(`2019 AOD: ${mean2019?.toFixed(3)}, Pixels: ${count2019px}`);
  print(`2020 AOD: ${mean2020?.toFixed(3)}, Pixels: ${count2020px}`);

  // Check for valid pixels
  if (count2019px === 0 || count2020px === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (mean2019 === null || mean2020 === null || 
      isNaN(mean2019) || isNaN(mean2020) ||
      mean2019 < 0 || mean2020 < 0) {
    print("<answer>C3</answer>");
    return;
  }

  // Compare AOD values
  if (mean2020 > mean2019) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
